import fse from 'fs-extra';
import { ensureDirSync } from 'fs-extra';
const { readJsonSync, outputFileSync, removeSync, pathExistsSync } = fse;
import os from 'node:os'; import path from 'node:path';
const d = path.join(os.tmpdir(), 'm34fse-' + process.pid);
ensureDirSync(path.join(d, 'a/b'));
outputFileSync(path.join(d, 'a/b/x.json'), JSON.stringify({ k: 1 }));
console.log(readJsonSync(path.join(d, 'a/b/x.json')), typeof fse.move);
fse.copySync(path.join(d, 'a'), path.join(d, 'c'));
console.log(pathExistsSync(path.join(d, 'c/b/x.json')));
await fse.writeJson(path.join(d, 'y.json'), { z: [1] }); console.log(await fse.readJson(path.join(d, 'y.json')));
await fse.move(path.join(d, 'y.json'), path.join(d, 'z.json')); console.log(await fse.pathExists(path.join(d, 'z.json')));
removeSync(d); console.log(pathExistsSync(d));
